from flask import Flask, session, redirect, url_for, render_template_string

app = Flask(__name__)
app.secret_key = 'your-secret-key'  # يجب تغييره إلى مفتاح آمن في الإنتاج

# تخزين بيانات المستخدمين (في التطبيق الحقيقي، استخدم قاعدة بيانات)
users = {
    'john': {
        'email': 'john@example.com',
        'ssn': '1234567890'
    },
    'jane': {
        'email': 'jane@example.com',
        'ssn': '0987654321'
    }
}

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        if username in users:
            session['username'] = username
            return redirect(url_for('info'))
        else:
            return "اسم المستخدم غير صحيح", 401
    return '''
    <form method="post">
        <input type="text" name="username" placeholder="اسم المستخدم" required>
        <button type="submit">تسجيل الدخول</button>
    </form>
    '''

@app.route('/info', methods=['GET'])
def info():
    if 'username' not in session:
        return redirect(url_for('login'))

    username = session['username']
    user_data = users[username]
    email = user_data['email']
    ssn_last_4 = user_data['ssn'][-4:]

    html = f'''
    <h1>معلومات المستخدم</h1>
    <p><strong>اسم المستخدم:</strong> {username}</p>
    <p><strong>البريد الإلكتروني:</strong> {email}</p>
    <p><strong>آخر 4 أرقام من رقم الضمان الاجتماعي:</strong> {ssn_last_4}</p>
    <a href="/logout">تسجيل الخروج</a>
    '''
    return html

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
